module find_rectangle (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] n,\n    input wire [31:0] m,\n    input wire [31:0] x,\n    input wire [31:0] y,\n    input wire [31:0] a,\n    input wire [31:0] b,\n    output reg [31:0] x1,\n    output reg [31:0] y1,\n    output reg [31:0] x2,\n    output reg [31:0] y2,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE    = 4'd0;\n    localparam [3:0] S_GCD     = 4'd1;\n    localparam [3:0] S_REDUCE  = 4'd2;\n    localparam [3:0] S_SCALE   = 4'd3;\n    localparam [3:0] S_POSITION= 4'd4;\n    localparam [3:0] S_DONE    = 4'd5;\n\n    reg [3:0] state;\n    reg [3:0] next_state;\n    \n    // Internal registers\n    reg [31:0] gcd_a;\n    reg [31:0] gcd_b;\n    reg [31:0] gcd_temp;\n    reg [31:0] a_reduced;\n    reg [31:0] b_reduced;\n    reg [31:0] k;\n    reg [31:0] width;\n    reg [31:0] height;\n    reg [31:0] cx;\n    reg [31:0] cy;\n    reg [31:0] dx;\n    reg [31:0] dy;\n    reg [31:0] max_k;\n    reg [31:0] div_temp;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        case (state)\n            S_IDLE:     next_state = start ? S_GCD : S_IDLE;\n            S_GCD:      next_state = (gcd_b == 0) ? S_REDUCE : S_GCD;\n            S_REDUCE:   next_state = S_SCALE;\n            S_SCALE:    next_state = S_POSITION;\n            S_POSITION: next_state = S_DONE;\n            S_DONE:     next_state = S_IDLE;\n            default:    next_state = S_IDLE;\n        endcase\n    end\n    \n    // Datapath logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize ALL registers\n            x1 <= 32'd0;\n            y1 <= 32'd0;\n            x2 <= 32'd0;\n            y2 <= 32'd0;\n            done <= 1'b0;\n            gcd_a <= 32'd0;\n            gcd_b <= 32'd0;\n            a_reduced <= 32'd0;\n            b_reduced <= 32'd0;\n            k <= 32'd0;\n            width <= 32'd0;\n            height <= 32'd0;\n            cx <= 32'd0;\n            cy <= 32'd0;\n            dx <= 32'd0;\n            dy <= 32'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        gcd_a <= a;\n                        gcd_b <= b;\n                    end\n                end\n                \n                S_GCD: begin\n                    if (gcd_b != 0) begin\n                        gcd_temp <= gcd_a % gcd_b;\n                        gcd_a <= gcd_b;\n                        gcd_b <= gcd_temp;\n                    end\n                end\n                \n                S_REDUCE: begin\n                    a_reduced <= a / gcd_a;\n                    b_reduced <= b / gcd_a;\n                end\n                \n                S_SCALE: begin\n                    k <= (n/a_reduced < m/b_reduced) ? n/a_reduced : m/b_reduced;\n                    width <= a_reduced * k;\n                    height <= b_reduced * k;\n                end\n                \n                S_POSITION: begin\n                    cx <= (width + 32'd1) >> 1;  // Center x\n                    cy <= (height + 32'd1) >> 1; // Center y\n                    \n                    // Initial dx, dy from position\n                    dx <= (x >= cx) ? (x - cx) : 32'd0;\n                    dy <= (y >= cy) ? (y - cy) : 32'd0;\n                    \n                    // Boundary clamping\n                    if ((dx + width) > n) dx <= n - width;\n                    if ((dy + height) > m) dy <= m - height;\n                    \n                    // Final coordinates\n                    x1 <= dx;\n                    y1 <= dy;\n                    x2 <= dx + width;\n                    y2 <= dy + height;\n                end\n                \n                S_DONE: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\nendmodule